// Get server time and prepare signature components
const serverTimeResponse = $input.first().json;
const serverTime = serverTimeResponse.serverTime;

// Add small offset for network latency
const timestamp = serverTime + 1000;

// API credentials
const apiKey = 'SUA_ASTER_API_KEY';
const apiSecret = 'SUA_ASTER_API_SECRET';

// Build query string for balance endpoint
const recvWindow = 60000;
const queryString = `recvWindow=${recvWindow}&timestamp=${timestamp}`;

console.log('Server Time:', new Date(serverTime).toISOString());
console.log('Using Timestamp:', timestamp);
console.log('Query String:', queryString);

return {
  timestamp: timestamp,
  recvWindow: recvWindow,
  apiKey: apiKey,
  apiSecret: apiSecret,
  queryString: queryString,
  serverTime: serverTime
};

// Process balance data - handle n8n HTTP Request node output
// O nó HTTP Request do n8n já retorna o array diretamente quando a resposta é um array JSON

// Pegar todos os itens do array
const balances = $input.all().map(item => item.json);

console.log('Total items received:', balances.length);
console.log('First item sample:', JSON.stringify(balances[0]).substring(0, 200));

// Check for API error in first item
if (balances.length > 0 && balances[0].code) {
  return {
    success: false,
    error: {
      code: balances[0].code,
      message: balances[0].msg
    }
  };
}

// Filter assets with actual balance or available balance
const activeAssets = balances.filter(b => {
  const balance = parseFloat(b.balance || 0);
  const availableBalance = parseFloat(b.availableBalance || 0);
  const crossWalletBalance = parseFloat(b.crossWalletBalance || 0);

  // Include if any balance is greater than 0
  return balance > 0 || availableBalance > 0 || crossWalletBalance > 0;
});

// Separate real balances from available balances
const realBalances = activeAssets.filter(b => parseFloat(b.balance || 0) > 0);
const availableOnly = activeAssets.filter(b =>
  parseFloat(b.balance || 0) === 0 && parseFloat(b.availableBalance || 0) > 0
);

// Calculate total values
let totalBalance = 0;
let totalAvailable = 0;
let totalUnrealizedPnL = 0;

// Process USDT and USDF as main currencies
const usdtAsset = balances.find(b => b.asset === 'USDT');
const usdfAsset = balances.find(b => b.asset === 'USDF');

if (usdtAsset) {
  totalBalance += parseFloat(usdtAsset.balance || 0);
  totalAvailable += parseFloat(usdtAsset.availableBalance || 0);
  totalUnrealizedPnL += parseFloat(usdtAsset.crossUnPnl || 0);
}

if (usdfAsset) {
  totalBalance += parseFloat(usdfAsset.balance || 0);
  totalAvailable += parseFloat(usdfAsset.availableBalance || 0);
  totalUnrealizedPnL += parseFloat(usdfAsset.crossUnPnl || 0);
}

// Format assets for output
const formattedAssets = activeAssets.map(asset => ({
  asset: asset.asset,
  balance: parseFloat(asset.balance || 0).toFixed(8),
  crossWalletBalance: parseFloat(asset.crossWalletBalance || 0).toFixed(8),
  crossUnPnl: parseFloat(asset.crossUnPnl || 0).toFixed(8),
  availableBalance: parseFloat(asset.availableBalance || 0).toFixed(8),
  maxWithdrawAmount: parseFloat(asset.maxWithdrawAmount || 0).toFixed(8),
  marginAvailable: asset.marginAvailable,
  lastUpdate: asset.updateTime > 0 ? new Date(asset.updateTime).toISOString() : 'N/A'
})).sort((a, b) => {
  // Sort by balance descending first, then by available balance
  const balanceA = parseFloat(a.balance);
  const balanceB = parseFloat(b.balance);
  if (balanceB !== balanceA) return balanceB - balanceA;

  const availA = parseFloat(a.availableBalance);
  const availB = parseFloat(b.availableBalance);
  return availB - availA;
});

// Calculate totals including all stablecoins
const stablecoins = ['USDT', 'USDF', 'USDC', 'BUSD', 'CUSDT', 'VUSDT', 'USDCE', 'USDBC', 'USD1', 'LISUSD', 'BONUSUSD'];
let totalStablecoinBalance = 0;
let totalStablecoinAvailable = 0;

stablecoins.forEach(coin => {
  const asset = balances.find(b => b.asset === coin);
  if (asset) {
    totalStablecoinBalance += parseFloat(asset.balance || 0);
    totalStablecoinAvailable += parseFloat(asset.availableBalance || 0);
  }
});

return {
  success: true,
  timestamp: new Date().toISOString(),
  dataType: 'balance',
  summary: {
    totalAssets: balances.length,
    assetsWithBalance: realBalances.length,
    assetsWithAvailableOnly: availableOnly.length,
    totalBalance: totalBalance.toFixed(2),
    totalAvailable: totalAvailable.toFixed(2),
    totalUnrealizedPnL: totalUnrealizedPnL.toFixed(2),
    totalStablecoinBalance: totalStablecoinBalance.toFixed(2),
    totalStablecoinAvailable: totalStablecoinAvailable.toFixed(2),
    mainCurrencies: {
      USDT: usdtAsset ? {
        balance: parseFloat(usdtAsset.balance || 0).toFixed(2),
        available: parseFloat(usdtAsset.availableBalance || 0).toFixed(2),
        unrealizedPnL: parseFloat(usdtAsset.crossUnPnl || 0).toFixed(2)
      } : null,
      USDF: usdfAsset ? {
        balance: parseFloat(usdfAsset.balance || 0).toFixed(2),
        available: parseFloat(usdfAsset.availableBalance || 0).toFixed(2),
        unrealizedPnL: parseFloat(usdfAsset.crossUnPnl || 0).toFixed(2)
      } : null
    }
  },
  assets: formattedAssets.slice(0, 20), // Top 20 assets
  realBalances: realBalances.map(b => ({
    asset: b.asset,
    balance: parseFloat(b.balance).toFixed(8),
    available: parseFloat(b.availableBalance || 0).toFixed(8)
  })),
  availableBalances: availableOnly.slice(0, 15).map(b => ({
    asset: b.asset,
    available: parseFloat(b.availableBalance).toFixed(8)
  }))
};

// Portfolio Analysis - Fixed Version 3.0
const inputs = $input.all();

// Configuration constants
const CONFIG = {
  RISK_THRESHOLDS: {
    CRITICAL: 5,
    HIGH: 10,
    MEDIUM: 20
  },
  LOSS_THRESHOLDS: {
    SEVERE: -50,
    HIGH: -20,
    WARNING: -10
  },
  PRECISION: {
    CURRENCY: 2,
    PRICE: 4,
    AMOUNT: 8,
    PERCENT: 2
  },
  MIN_BALANCE_DISPLAY: 0.01
};

// Utility functions
const formatNumber = (value, precision = CONFIG.PRECISION.CURRENCY) => {
  const num = parseFloat(value || 0);
  return isNaN(num) ? '0.00' : num.toFixed(precision);
};

const calculatePercentage = (value, total) => {
  if (!total || total === 0) return 0;
  return (value / total) * 100;
};

// Parse input data
function parseInputData(inputs) {
  let balanceData = null;
  let accountData = null;
  const errors = [];

  for (const item of inputs) {
    const data = item.json;

    if (data?.error || data?.code) {
      errors.push({
        type: 'API_ERROR',
        message: data.error?.message || 'Unknown error'
      });
      continue;
    }

    if (data?.dataType === 'balance' || data?.summary?.totalAssets !== undefined) {
      balanceData = data;
    } else if (data?.positions !== undefined || data?.totalWalletBalance !== undefined) {
      accountData = data;
    }
  }

  return { balanceData, accountData, errors };
}

// Process position with proper price calculation
function processPosition(position, accountData) {
  const positionAmt = parseFloat(position.positionAmt || 0);
  if (positionAmt === 0) return null;

  const entryPrice = parseFloat(position.entryPrice || 0);
  const unrealizedProfit = parseFloat(position.unrealizedProfit || 0);
  const notional = parseFloat(position.notional || 0);

  // Calculate current price from notional value if markPrice is missing or zero
  let markPrice = parseFloat(position.markPrice || 0);
  if (markPrice === 0 && Math.abs(positionAmt) > 0) {
    // Try to calculate from notional
    if (Math.abs(notional) > 0) {
      markPrice = Math.abs(notional / positionAmt);
    } else if (entryPrice > 0 && unrealizedProfit !== 0) {
      // Estimate from entry price and unrealized profit
      const profitPerUnit = unrealizedProfit / Math.abs(positionAmt);
      markPrice = positionAmt > 0 ? 
        entryPrice + profitPerUnit : 
        entryPrice - profitPerUnit;

      // Ensure mark price doesn't go negative
      if (markPrice < 0) markPrice = 0.0001;
    }
  }

  // Calculate actual PnL percentage
  let pnlPercent = 0;
  let totalInvested = Math.abs(positionAmt * entryPrice);

  if (entryPrice > 0 && markPrice > 0) {
    const priceChange = markPrice - entryPrice;
    pnlPercent = (priceChange / entryPrice) * 100;
    if (positionAmt < 0) pnlPercent = -pnlPercent; // Reverse for short positions
  } else if (totalInvested > 0 && unrealizedProfit !== 0) {
    // Calculate from unrealized profit
    pnlPercent = (unrealizedProfit / totalInvested) * 100;
  }

  // Determine risk level based on loss percentage and margin
  let riskLevel = 'LOW';
  const absLoss = Math.abs(pnlPercent);

  if (absLoss > 80 || pnlPercent < -80) {
    riskLevel = 'CRITICAL';
  } else if (absLoss > 50 || pnlPercent < -50) {
    riskLevel = 'HIGH';
  } else if (absLoss > 20 || pnlPercent < -20) {
    riskLevel = 'MEDIUM';
  }

  // Check margin level for additional risk assessment
  const leverage = parseFloat(position.leverage || 1);
  const marginRatio = leverage > 1 ? (100 / leverage) : 100;
  if (marginRatio < 10 && riskLevel === 'LOW') {
    riskLevel = 'MEDIUM';
  }

  // Generate alerts
  const alerts = [];
  if (pnlPercent < CONFIG.LOSS_THRESHOLDS.SEVERE) {
    alerts.push({
      type: 'SEVERE_LOSS',
      severity: 'CRITICAL',
      symbol: position.symbol,
      side: positionAmt > 0 ? 'LONG' : 'SHORT',
      pnl: formatNumber(unrealizedProfit),
      pnlPercent: formatNumber(pnlPercent, CONFIG.PRECISION.PERCENT),
      message: `${position.symbol} ${positionAmt > 0 ? 'LONG' : 'SHORT'} has severe loss of ${formatNumber(pnlPercent, CONFIG.PRECISION.PERCENT)}%`,
      action: 'CONSIDER_CLOSING_POSITION'
    });
  } else if (pnlPercent < CONFIG.LOSS_THRESHOLDS.HIGH) {
    alerts.push({
      type: 'LARGE_LOSS',
      severity: 'HIGH',
      symbol: position.symbol,
      side: positionAmt > 0 ? 'LONG' : 'SHORT',
      pnl: formatNumber(unrealizedProfit),
      pnlPercent: formatNumber(pnlPercent, CONFIG.PRECISION.PERCENT),
      message: `${position.symbol} ${positionAmt > 0 ? 'LONG' : 'SHORT'} has large loss of ${formatNumber(pnlPercent, CONFIG.PRECISION.PERCENT)}%`,
      action: 'REVIEW_POSITION'
    });
  }

  return {
    data: {
      symbol: position.symbol,
      side: positionAmt > 0 ? 'LONG' : 'SHORT',
      amount: formatNumber(Math.abs(positionAmt), CONFIG.PRECISION.AMOUNT),
      notional: formatNumber(Math.abs(notional)),
      entryPrice: formatNumber(entryPrice, CONFIG.PRECISION.PRICE),
      markPrice: markPrice > 0 ? formatNumber(markPrice, CONFIG.PRECISION.PRICE) : 'N/A',
      currentValue: formatNumber(Math.abs(positionAmt * markPrice)),
      unrealizedProfit: formatNumber(unrealizedProfit),
      pnlPercent: formatNumber(pnlPercent, CONFIG.PRECISION.PERCENT),
      leverage: leverage.toString(),
      marginType: position.marginType || (position.isolated ? 'isolated' : 'cross'),
      hasValidPrice: markPrice > 0
    },
    alerts,
    riskLevel
  };
}

// Process account info
function processAccountInfo(accountData) {
  if (!accountData || accountData.code || accountData.error) {
    return null;
  }

  const totalWallet = parseFloat(accountData.totalWalletBalance || 0);
  const totalMargin = parseFloat(accountData.totalPositionInitialMargin || 0);
  const availableBalance = parseFloat(accountData.availableBalance || 0);

  return {
    totalWalletBalance: formatNumber(totalWallet),
    totalUnrealizedProfit: formatNumber(accountData.totalUnrealizedProfit),
    totalMarginBalance: formatNumber(accountData.totalMarginBalance),
    availableBalance: formatNumber(availableBalance),
    totalPositionInitialMargin: formatNumber(totalMargin),
    totalOpenOrderInitialMargin: formatNumber(accountData.totalOpenOrderInitialMargin),
    totalCrossWalletBalance: formatNumber(accountData.totalCrossWalletBalance),
    totalCrossUnPnl: formatNumber(accountData.totalCrossUnPnl),
    maxWithdrawAmount: formatNumber(accountData.maxWithdrawAmount),
    marginUsagePercent: totalWallet > 0 ? 
      formatNumber((totalMargin / totalWallet) * 100, CONFIG.PRECISION.PERCENT) : '0.00'
  };
}

// Main analysis function
function analyzePortfolio(inputs) {
  const { balanceData, accountData, errors } = parseInputData(inputs);

  if (!balanceData || !balanceData.success) {
    return {
      success: false,
      error: balanceData?.error || 'Balance data not received',
      timestamp: new Date().toISOString()
    };
  }

  const portfolio = {
    timestamp: new Date().toISOString(),
    positions: [],
    alerts: [],
    riskLevel: 'LOW',
    metrics: {
      totalPositions: 0,
      profitablePositions: 0,
      losingPositions: 0,
      averagePnL: 0
    }
  };

  const accountInfo = processAccountInfo(accountData);

  // Process positions
  if (accountData?.positions && Array.isArray(accountData.positions)) {
    let totalPnL = 0;

    for (const position of accountData.positions) {
      const processed = processPosition(position, accountData);
      if (!processed) continue;

      portfolio.positions.push(processed.data);
      portfolio.alerts.push(...processed.alerts);

      // Update metrics
      portfolio.metrics.totalPositions++;
      const pnl = parseFloat(processed.data.pnlPercent);
      totalPnL += pnl;

      if (pnl > 0) {
        portfolio.metrics.profitablePositions++;
      } else if (pnl < 0) {
        portfolio.metrics.losingPositions++;
      }

      // Update risk level
      if (processed.riskLevel === 'CRITICAL') {
        portfolio.riskLevel = 'CRITICAL';
      } else if (processed.riskLevel === 'HIGH' && portfolio.riskLevel !== 'CRITICAL') {
        portfolio.riskLevel = 'HIGH';
      } else if (processed.riskLevel === 'MEDIUM' && portfolio.riskLevel === 'LOW') {
        portfolio.riskLevel = 'MEDIUM';
      }
    }

    portfolio.metrics.averagePnL = portfolio.metrics.totalPositions > 0 ? 
      formatNumber(totalPnL / portfolio.metrics.totalPositions, CONFIG.PRECISION.PERCENT) : '0.00';
  }

  // Check for data inconsistencies
  const warnings = [];
  const reportedPnL = parseFloat(balanceData.summary.totalUnrealizedPnL || 0);
  const calculatedPnL = portfolio.positions.reduce((sum, pos) => 
    sum + parseFloat(pos.unrealizedProfit), 0
  );

  if (Math.abs(reportedPnL - calculatedPnL) > 1 && portfolio.positions.length === 0) {
    warnings.push({
      type: 'DATA_INCONSISTENCY',
      message: 'Unrealized PnL detected but no open positions found',
      suggestion: 'Check if all positions are being loaded correctly'
    });
  }

  return {
    success: true,
    timestamp: portfolio.timestamp,
    riskLevel: portfolio.riskLevel,
    hasAlerts: portfolio.alerts.length > 0,
    hasErrors: errors.length > 0,
    summary: {
      totalAssets: balanceData.summary.totalAssets,
      assetsWithBalance: balanceData.summary.assetsWithBalance,
      totalWalletBalance: accountInfo?.totalWalletBalance || balanceData.summary.totalBalance,
      totalUnrealizedPnL: accountInfo?.totalUnrealizedProfit || balanceData.summary.totalUnrealizedPnL,
      availableBalance: accountInfo?.availableBalance || balanceData.summary.totalAvailable,
      totalStablecoinBalance: balanceData.summary.totalStablecoinBalance,
      totalStablecoinAvailable: balanceData.summary.totalStablecoinAvailable,
      mainCurrencies: balanceData.summary.mainCurrencies,
      openPositions: portfolio.positions.length,
      totalAlerts: portfolio.alerts.length,
      marginUsagePercent: accountInfo?.marginUsagePercent || '0.00%'
    },
    metrics: portfolio.metrics,
    positions: portfolio.positions,
    alerts: portfolio.alerts,
    apiErrors: errors,
    warnings,
    topAssets: balanceData.assets ? 
      balanceData.assets.filter(a => parseFloat(a.balance) >= CONFIG.MIN_BALANCE_DISPLAY).slice(0, 10) : [],
    accountInfo,
    notification: generateNotification(portfolio, errors),
    requiresAction: portfolio.alerts.some(a => a.severity === 'CRITICAL' || a.severity === 'HIGH')
  };
}

function generateNotification(portfolio, errors) {
  if (errors.length > 0) {
    return 'ℹ️ API issues detected - Data may be incomplete';
  }

  if (portfolio.alerts.length > 0) {
    const critical = portfolio.alerts.filter(a => a.severity === 'CRITICAL').length;
    return critical > 0 ? 
      `🚨 ${critical} CRITICAL alert(s) - Risk: ${portfolio.riskLevel}` :
      `⚠️ ${portfolio.alerts.length} alert(s) - Risk: ${portfolio.riskLevel}`;
  }

  if (portfolio.positions.length > 0) {
    return `📊 ${portfolio.positions.length} position(s) active - Risk: ${portfolio.riskLevel}`;
  }

  return '💤 No open positions';
}

// Execute
try {
  return analyzePortfolio(inputs);
} catch (error) {
  return {
    success: false,
    error: `Analysis failed: ${error.message}`,
    timestamp: new Date().toISOString()
  };
}

// Enhanced Portfolio Message Formatter v2.0
const data = $json;

// Configuration
const CONFIG = {
  LOCALE: 'pt-BR',
  TIMEZONE: 'America/Sao_Paulo',
  CURRENCY_SYMBOL: '$',
  MIN_DISPLAY_VALUE: 0.01
};

// Utility functions
const formatCurrency = (value, showSign = false) => {
  const num = parseFloat(value || 0);
  const formatted = num.toFixed(2);
  if (showSign && num > 0) return `+${CONFIG.CURRENCY_SYMBOL}${formatted}`;
  return `${CONFIG.CURRENCY_SYMBOL}${formatted}`;
};

const formatPercent = (value, showSign = true) => {
  const num = parseFloat(value || 0);
  const formatted = num.toFixed(2);
  if (showSign && num > 0) return `+${formatted}%`;
  return `${formatted}%`;
};

const formatDateTime = (timestamp) => {
  const date = new Date(timestamp);
  return date.toLocaleString(CONFIG.LOCALE, {
    timeZone: CONFIG.TIMEZONE,
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
};

// Component builders
const buildHeader = (data) => {
  const riskIcons = {
    'LOW': '🟢',
    'MEDIUM': '🟡', 
    'HIGH': '🟠',
    'CRITICAL': '🔴'
  };

  let header = `📊 **BINANCE FUTURES PORTFOLIO**\n`;
  header += `━━━━━━━━━━━━━━━━━━━━━━━━\n`;
  header += `⏰ ${formatDateTime(data.timestamp)}\n`;
  header += `${riskIcons[data.riskLevel]} Risk: **${data.riskLevel}**`;

  // Add margin usage if available
  if (data.summary.marginUsagePercent && data.summary.marginUsagePercent !== '0.00%') {
    header += ` | Margin Used: ${data.summary.marginUsagePercent}`;
  }

  header += `\n`;

  return header;
};

const buildBalanceSection = (summary) => {
  const pnl = parseFloat(summary.totalUnrealizedPnL || 0);
  const pnlIcon = pnl >= 0 ? '📈' : '📉';
  const pnlColor = pnl >= 0 ? '🟢' : '🔴';

  let section = `\n💰 **ACCOUNT BALANCE**\n`;

  // Main balance info
  section += `┌─ Wallet Balance: **${formatCurrency(summary.totalWalletBalance)}**\n`;
  section += `├─ Available: ${formatCurrency(summary.availableBalance)}`;

  // Show available percentage if relevant
  const totalBalance = parseFloat(summary.totalWalletBalance);
  const available = parseFloat(summary.availableBalance);
  if (totalBalance > 0) {
    const availPercent = ((available / totalBalance) * 100).toFixed(1);
    section += ` (${availPercent}% free)`;
  }
  section += `\n`;

  // PnL with better formatting
  section += `├─ Unrealized P&L: ${pnlColor} **${formatCurrency(pnl, true)}**`;
  if (totalBalance > 0 && pnl !== 0) {
    const pnlPercent = ((pnl / totalBalance) * 100).toFixed(2);
    section += ` (${formatPercent(pnlPercent)})`;
  }
  section += `\n`;

  // Stablecoins breakdown
  const usdtBalance = parseFloat(summary.mainCurrencies.USDT?.balance || 0);
  const usdfBalance = parseFloat(summary.mainCurrencies.USDF?.balance || 0);

  if (usdtBalance >= CONFIG.MIN_DISPLAY_VALUE || usdfBalance >= CONFIG.MIN_DISPLAY_VALUE) {
    section += `└─ Stablecoins:\n`;
    if (usdtBalance >= CONFIG.MIN_DISPLAY_VALUE) {
      section += `   ├─ USDT: ${formatCurrency(usdtBalance)}`;
      const usdtPnL = parseFloat(summary.mainCurrencies.USDT?.unrealizedPnL || 0);
      if (usdtPnL !== 0) {
        section += ` (P&L: ${formatCurrency(usdtPnL, true)})`;
      }
      section += `\n`;
    }
    if (usdfBalance >= CONFIG.MIN_DISPLAY_VALUE) {
      section += `   └─ USDF: ${formatCurrency(usdfBalance)}\n`;
    }
  } else {
    section += `└─ All Stablecoins: ${formatCurrency(summary.totalStablecoinBalance)}\n`;
  }

  return section;
};

const buildPositionsSection = (positions, metrics) => {
  if (!positions || positions.length === 0) {
    return `\n📈 **POSITIONS**\nNo open positions\n`;
  }

  let section = `\n📈 **OPEN POSITIONS** (${positions.length})`;

  // Add metrics summary if available
  if (metrics && metrics.totalPositions > 0) {
    section += `\n📊 Win Rate: ${metrics.profitablePositions}/${metrics.totalPositions}`;
    if (metrics.averagePnL) {
      section += ` | Avg P&L: ${formatPercent(metrics.averagePnL)}`;
    }
  }
  section += `\n`;

  // Sort positions by risk level then by PnL
  const sortedPositions = [...positions].sort((a, b) => {
    const riskOrder = { 'CRITICAL': 0, 'HIGH': 1, 'MEDIUM': 2, 'LOW': 3 };
    const riskDiff = riskOrder[a.riskLevel] - riskOrder[b.riskLevel];
    if (riskDiff !== 0) return riskDiff;
    return parseFloat(b.unrealizedProfit) - parseFloat(a.unrealizedProfit);
  });

  sortedPositions.forEach((pos, index) => {
    const pnlValue = parseFloat(pos.unrealizedProfit);
    const pnlPercent = parseFloat(pos.pnlPercent);
    const isLastItem = index === sortedPositions.length - 1;

    // Position header with better icons
    let posIcon = pos.side === 'LONG' ? '📊' : '📉';
    let pnlIcon = pnlValue >= 0 ? '✅' : (pnlValue < -20 ? '🔴' : '⚠️');

    section += `\n${isLastItem ? '└' : '├'}─ **${pos.symbol}** ${pos.side} ${pos.leverage}x\n`;

    // Compact but informative display
    section += `   ${isLastItem ? ' ' : '│'} Entry: ${formatCurrency(pos.entryPrice)} → ${formatCurrency(pos.markPrice)}\n`;
    section += `   ${isLastItem ? ' ' : '│'} P&L: ${pnlIcon} ${formatCurrency(pnlValue, true)} (${pos.pnlPercent})\n`;

    // Show liquidation info only if relevant
    if (pos.liquidationPrice !== 'N/A' && pos.liquidationPrice !== 'Estimated') {
      const liqDistance = parseFloat(pos.liquidationDistance);
      let liqWarning = '';
      if (liqDistance < 5) liqWarning = ' ⚠️ CRITICAL';
      else if (liqDistance < 10) liqWarning = ' ⚠️';

      section += `   ${isLastItem ? ' ' : '│'} Liq: ${formatCurrency(pos.liquidationPrice)} (${pos.liquidationDistance}${liqWarning})\n`;
    }

    // Risk level only if not LOW
    if (pos.riskLevel !== 'LOW') {
      const riskIcons = { 'MEDIUM': '🟡', 'HIGH': '🟠', 'CRITICAL': '🔴' };
      section += `   ${isLastItem ? ' ' : '│'} Risk: ${riskIcons[pos.riskLevel]} ${pos.riskLevel}\n`;
    }
  });

  return section;
};

const buildAlertsSection = (alerts) => {
  if (!alerts || alerts.length === 0) return '';

  // Group alerts by severity
  const grouped = {
    CRITICAL: [],
    HIGH: [],
    MEDIUM: [],
    LOW: []
  };

  alerts.forEach(alert => {
    grouped[alert.severity].push(alert);
  });

  let section = `\n⚠️ **ALERTS** (${alerts.length})\n`;

  // Display by priority
  Object.entries(grouped).forEach(([severity, severityAlerts]) => {
    if (severityAlerts.length === 0) return;

    const severityIcons = {
      'CRITICAL': '🔴',
      'HIGH': '🟠',
      'MEDIUM': '🟡',
      'LOW': '🟢'
    };

    severityAlerts.forEach(alert => {
      section += `${severityIcons[severity]} ${alert.message}`;
      if (alert.action && alert.action !== 'MONITOR') {
        const actionText = alert.action.replace(/_/g, ' ').toLowerCase();
        section += ` → ${actionText}`;
      }
      section += `\n`;
    });
  });

  return section;
};

const buildErrorsSection = (apiErrors, warnings) => {
  if ((!apiErrors || apiErrors.length === 0) && (!warnings || warnings.length === 0)) {
    return '';
  }

  let section = `\n⚠️ **ISSUES DETECTED**\n`;

  // API Errors
  if (apiErrors && apiErrors.length > 0) {
    apiErrors.forEach(error => {
      // Parse the specific error type
      if (error.message.includes('-1021')) {
        section += `🔄 Sync Issue: Time synchronization problem detected\n`;
        section += `   → Solution: Check system time or contact support\n`;
      } else if (error.message.includes('-2015')) {
        section += `🔑 Auth Issue: API key problem detected\n`;
        section += `   → Solution: Verify API key and permissions\n`;
      } else if (error.message.includes('-1003')) {
        section += `⏱️ Rate Limit: Too many requests\n`;
        section += `   → Solution: Reduce request frequency\n`;
      } else {
        section += `ℹ️ API Issue: ${error.solution}\n`;
      }
    });
  }

  // Data Warnings
  if (warnings && warnings.length > 0) {
    warnings.forEach(warning => {
      if (warning.type === 'DATA_INCONSISTENCY') {
        section += `📊 Data Warning: ${warning.message}\n`;
        section += `   → ${warning.suggestion}\n`;
      } else {
        section += `ℹ️ ${warning.message}\n`;
      }
    });
  }

  return section;
};

const buildFooter = (data) => {
  let footer = `\n━━━━━━━━━━━━━━━━━━━━━━━━\n`;

  // Add quick status summary
  const hasIssues = data.hasErrors || (data.warnings && data.warnings.length > 0);
  const hasAlerts = data.hasAlerts;

  if (data.requiresAction) {
    footer += `⚠️ **ACTION REQUIRED** - Please review alerts above\n`;
  } else if (hasIssues) {
    footer += `ℹ️ Some issues detected - Data may be incomplete\n`;
  } else if (data.positions && data.positions.length > 0) {
    const totalPnL = parseFloat(data.summary.totalUnrealizedPnL || 0);
    if (totalPnL > 0) {
      footer += `✅ Portfolio in profit: ${formatCurrency(totalPnL, true)}\n`;
    } else if (totalPnL < 0) {
      footer += `📉 Portfolio at loss: ${formatCurrency(totalPnL)}\n`;
    } else {
      footer += `📊 Portfolio at breakeven\n`;
    }
  } else {
    footer += `💤 No active positions\n`;
  }

  return footer;
};

// Main message builder
const buildMessage = (data) => {
  try {
    let message = '';

    // Build sections
    message += buildHeader(data);
    message += buildBalanceSection(data.summary);
    message += buildPositionsSection(data.positions, data.metrics);
    message += buildAlertsSection(data.alerts);
    message += buildErrorsSection(data.apiErrors, data.warnings);
    message += buildFooter(data);

    return message;
  } catch (error) {
    // Fallback message on error
    return `📊 **PORTFOLIO UPDATE**\n⚠️ Error formatting message: ${error.message}\nRaw data available in logs.`;
  }
};

// Execute
return { 
  message: buildMessage(data),
  success: data.success,
  requiresAction: data.requiresAction
};
